import math

limit = 15
successful_triples = []

for a in range(1, limit + 1):
    for b in range(1, limit + 1):
        for c in range(1, limit + 1):
            # Calculate E = sqrt(1001/a) + sqrt(1001/b) + sqrt(1001/c)
            try:
                E = math.sqrt(1001/a) + math.sqrt(1001/b) + math.sqrt(1001/c)
            except ValueError:
                # Should not happen since a, b, c >= 1
                continue

            # Check if E is an integer within tolerance
            is_integer = abs(E - round(E)) < 1e-9

            if is_integer:
                successful_triples.append((a, b, c))

print(f"Found {len(successful_triples)} triples.")
print("Triples found:")
for triple in successful_triples:
    print(triple)
